<?php
namespace App\Http\Controllers;
use App\Models\{AuditLog,Department,EdrFeedback,EdrReport,PeriodicPerformance,Plan,WeeklyPerformance};
use App\Services\{CalendarHelper,ScoreCalculator,WorkflowNotificationService};
use Barryvdh\DomPDF\Facade\Pdf;
use Illuminate\Http\Request;

class EdrFeedbackController extends Controller {
 public function __construct(private ScoreCalculator $scores,private WorkflowNotificationService $notifications) {}
 public function index(Request $r){$u=auth()->user();$years=CalendarHelper::getAppYears();$year=$r->filled('year')?(int)$r->input('year'):null;$period=$r->filled('period')?(string)$r->input('period'):null;$q=EdrFeedback::with(['department','preparer'])->when($year,fn($query)=>$query->where('year',$year))->when($period,fn($query)=>$query->where('reporting_period',$period));$this->scopeVisible($q,$u);$feedbacks=$q->latest('updated_at')->get()->sortByDesc->total_score->values();$departments=($u->isPlanReportDepartmentExpert()||$u->isSystemAdmin())?Department::where('is_active',true)->orderBy('name')->get():collect();$periodOptions=$this->periodOptions();return view('feedbacks.index',compact('feedbacks','departments','years','year','period','periodOptions'));}
 public function create(Request $r){abort_unless(auth()->user()->isPlanReportDepartmentExpert()||auth()->user()->isSystemAdmin(),403);return $this->form(new EdrFeedback(['department_id'=>$r->department_id,'year'=>$r->get('year',now()->year),'reporting_period'=>$r->get('period','annual')]));}
 public function edit(EdrFeedback $feedback){$this->authorizeEdit($feedback);return $this->form($feedback);}
 public function store(Request $r){abort_unless(auth()->user()->isPlanReportDepartmentExpert()||auth()->user()->isSystemAdmin(),403);$d=$this->validated($r);$this->attachPerformance($d);$d['prepared_by']=auth()->id();$d['status']='draft';$f=EdrFeedback::updateOrCreate(['department_id'=>$d['department_id'],'year'=>$d['year'],'reporting_period'=>$d['reporting_period']],$d);AuditLog::log('Feedback drafted',$f);return redirect()->route('feedbacks.edit',$f)->with('success','Feedback draft saved.');}
 public function update(Request $r,EdrFeedback $feedback){$this->authorizeEdit($feedback);$d=$this->validated($r);$d['department_id']=$feedback->department_id;$d['year']=$feedback->year;$d['reporting_period']=$feedback->reporting_period;$this->attachPerformance($d);unset($d['status']);$feedback->update($d);AuditLog::log('Feedback updated',$feedback);return redirect()->route('feedbacks.edit',$feedback)->with('success','Feedback changes saved.');}
 public function submit(EdrFeedback $feedback){abort_unless(auth()->user()->isPlanReportDepartmentExpert()&&$feedback->status==='draft',403);$feedback->update(['status'=>'submitted_to_plan_report_directorate']);$this->notifications->roles('plan_report_directorate','Feedback awaiting review','Department feedback was sent for Directorate review.',route('feedbacks.show',$feedback),'info',null,auth()->user());AuditLog::log('Feedback submitted to directorate',$feedback);return back()->with('success','Feedback sent to Plan and Report Directorate.');}
 public function forwardToHead(EdrFeedback $feedback){abort_unless(auth()->user()->isPlanReportDirectorate()&&$feedback->status==='submitted_to_plan_report_directorate',403);$feedback->update(['status'=>'submitted_to_plan_report_head','directorate_reviewed_by'=>auth()->id(),'directorate_reviewed_at'=>now()]);$this->notifications->roles('plan_report_head_office','Feedback awaiting approval','Reviewed department feedback was sent for final approval.',route('feedbacks.show',$feedback),'info',null,auth()->user());AuditLog::log('Feedback submitted to head',$feedback);return back()->with('success','Feedback sent to Plan and Report Head.');}
 public function finalize(EdrFeedback $feedback){abort_unless(auth()->user()->isPlanReportHeadOffice()&&$feedback->status==='submitted_to_plan_report_head',403);$d=$feedback->toArray();$this->attachPerformance($d,true);$feedback->update(['performance_percent'=>$d['performance_percent'],'performance_score'=>$d['performance_score'],'status'=>'finalized','head_approved_by'=>auth()->id(),'head_approved_at'=>now()]);$this->notifications->roles('department_chief','Official feedback released','Plan and Report has released finalized feedback for your department.',route('feedbacks.show',$feedback),'success',$feedback->department_id,auth()->user());AuditLog::log('Feedback finalized and released to department chief',$feedback);return back()->with('success','Feedback finalized and released to the department chief.');}
 public function show(EdrFeedback $feedback){$this->authorizeView($feedback);$feedback->load(['department','preparer']);return view('feedbacks.show',compact('feedback'));}
 public function pdf(EdrFeedback $feedback){$this->authorizeView($feedback);$feedback->load(['department','preparer']);return Pdf::loadView('feedbacks.pdf',compact('feedback'))->setPaper('a4')->download('EDR_Feedback_'.$feedback->department->code.'_'.$feedback->year.'_'.$feedback->reporting_period.'.pdf');}
 private function form(EdrFeedback $f){$departments=Department::where('is_active',true)->orderBy('name')->get();$years=CalendarHelper::getAppYears();$performance=$f->department_id?$this->performance((int)$f->department_id,(int)$f->year,(string)$f->reporting_period):null;$selectedReport=$f->department_id?EdrReport::with('department')->where('department_id',$f->department_id)->where('year',$f->year)->where('reporting_period',$f->reporting_period)->latest('updated_at')->first():null;$weeklyPreview=null;$monthlyPreview=null;if($f->department_id&&$performance&&preg_match('/^week:([a-z]+):([1-6])$/i',(string)$f->reporting_period,$m)){$weeklyPreview=['month'=>strtolower($m[1]),'week'=>(int)$m[2],'entries'=>$performance['entries']??0,'percent'=>$performance['percent']];}elseif($f->department_id&&$performance&&preg_match('/^month:([a-z]+)$/i',(string)$f->reporting_period,$m)){$monthlyPreview=['month'=>strtolower($m[1]),'entries'=>$performance['entries']??0,'percent'=>$performance['percent']];}return view('feedbacks.form',['feedback'=>$f,'departments'=>$departments,'years'=>$years,'performance'=>$performance,'selectedReport'=>$selectedReport,'weeklyPreview'=>$weeklyPreview,'monthlyPreview'=>$monthlyPreview,'periodOptions'=>$this->periodOptions()]);}
 private function validated(Request $r):array{return $r->validate(['department_id'=>'required|exists:departments,id','year'=>'required|integer','reporting_period'=>['required','string','regex:/^(annual|q[1-4]|month:[a-z]+|week:[a-z]+:[1-6])$/i'],'strengths'=>'nullable|string|max:20000','weaknesses'=>'nullable|string|max:20000','next_focus_areas'=>'nullable|string|max:20000','plan_quality_score'=>'required|numeric|min:0|max:5','report_quality_score'=>'required|numeric|min:0|max:8','submission_score'=>'required|numeric|min:0|max:7','status'=>'nullable|string']);}
 private function attachPerformance(array &$d,bool $required=false):void{$p=$this->performance((int)$d['department_id'],(int)$d['year'],$d['reporting_period']);if($required&&!$p)throw \Illuminate\Validation\ValidationException::withMessages(['status'=>'Feedback cannot be finalized until the department performance report is approved.']);$d['performance_percent']=$p['percent']??null;$d['performance_score']=$p['score']??null;}
 private function performance(int $dept,int $year,string $period):?array{$plan=Plan::where('department_id',$dept)->where('year',$year)->where('status','approved')->first();if(!$plan)return null;if(preg_match('/^week:([a-z]+):([1-6])$/i',$period,$m)){$values=WeeklyPerformance::whereIn('plan_item_id',$plan->items()->select('id'))->where('year',$year)->where('month',strtolower($m[1]))->where('week_number',(int)$m[2])->whereIn('workflow_status',['approved_by_head_office','reviewed_no_correction_required'])->where('planned_value','>',0)->pluck('percentage');if($values->isEmpty())return null;$percent=round((float)$values->average(),2);return ['percent'=>$percent,'score'=>round(min(100,$percent)*.8,2),'entries'=>$values->count()];}if(preg_match('/^month:([a-z]+)$/i',$period,$m)){$entries=PeriodicPerformance::whereIn('plan_item_id',$plan->items()->select('id'))->where('period',$year.'-'.strtolower($m[1]))->whereIn('workflow_status',['approved_by_head_office','reviewed_no_correction_required'])->count();if($entries===0)return null;$percent=$this->scores->calculateDepartmentAverage(Department::find($dept),$plan,strtolower($m[1]));return ['percent'=>$percent,'score'=>round(min(100,$percent)*.8,2),'entries'=>$entries];}if(!EdrReport::where('department_id',$dept)->where('year',$year)->where('reporting_period',$period)->where('status','approved')->exists())return null;$percent=$this->scores->calculateDepartmentAverage(Department::find($dept),$plan,$period);return ['percent'=>$percent,'score'=>round(min(100,$percent)*.8,2)];}
 private function periodOptions():array{$options=['annual'=>'Annual','q1'=>'Quarter 1','q2'=>'Quarter 2','q3'=>'Quarter 3','q4'=>'Quarter 4'];$months=['july','august','september','october','november','december','january','february','march','april','may','june'];foreach($months as $month){$options['month:'.$month]=ucfirst($month);for($week=1;$week<=5;$week++)$options['week:'.$month.':'.$week]=ucfirst($month).' — Week '.$week;}return $options;}
 private function workflowUser():bool{$u=auth()->user();return $u->isSystemAdmin()||$u->isPlanReportDepartmentExpert()||$u->isPlanReportDirectorate()||$u->isPlanReportHeadOffice();}
 private function authorizeEdit(EdrFeedback $f):void{$u=auth()->user();if($u->isSystemAdmin())return;abort_unless(($u->isPlanReportDepartmentExpert()&&$f->status==='draft')||($u->isPlanReportDirectorate()&&$f->status==='submitted_to_plan_report_directorate')||($u->isPlanReportHeadOffice()&&$f->status==='submitted_to_plan_report_head'),403);}
 private function authorizeView(EdrFeedback $f):void{$u=auth()->user();$q=EdrFeedback::whereKey($f->id);$this->scopeVisible($q,$u);abort_unless($u->hasPermission('view_feedbacks')&&$q->exists(),403);}
 private function scopeVisible($q,$u):void{if($u->isSystemAdmin()||$u->isPlanReportDepartmentExpert())return;if($u->isPlanReportDirectorate()){$q->whereIn('status',['submitted_to_plan_report_directorate','submitted_to_plan_report_head','finalized']);return;}if($u->isPlanReportHeadOffice()){$q->whereIn('status',['submitted_to_plan_report_head','finalized']);return;}if($u->isDepartmentChief()){$q->where('department_id',$u->department_id)->where('status','finalized');return;}$q->whereRaw('1 = 0');}
}
